package com.bank.fraud;

import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BfsDemo {

    private static final Logger log = Logger.getLogger(BfsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build the transfer graph as an adjacency list.
        Map<String, List<String>> graph = new java.util.HashMap<>();
        graph.put("SAV2001", List.of("CUR3001", "SAV4002")); // Rajesh → Priya, Amit
        graph.put("CUR3001", List.of("SAV5003"));             // Priya → Neha
        graph.put("SAV4002", List.of("SAV5003"));             // Amit → Neha
        graph.put("SAV5003", List.of("CUR6004"));             // Neha → Vijay
        graph.put("CUR6004", List.of());                      // Vijay → none

        MoneyFlowBFS bfs = new MoneyFlowBFS(graph);
        bfs.traverseFrom("SAV2001");
    }
}

