class MoneyFlowBFS {

    private static final Logger log = Logger.getLogger(MoneyFlowBFS.class.getName());

    private final Map<String, List<String>> graph;

    MoneyFlowBFS(Map<String, List<String>> graph) {
        this.graph = graph;
    }

    // Visit all reachable accounts ring by ring, tracking hop distance.
    void traverseFrom(String start) {
        java.util.Queue<String> queue = new java.util.LinkedList<>();
        java.util.Map<String, Integer> distance = new java.util.HashMap<>();
        java.util.Set<String> visited = new java.util.HashSet<>();

        queue.offer(start);
        visited.add(start);
        distance.put(start, 0);

        while (!queue.isEmpty()) {
            String current = queue.poll();                 // dequeue nearest unprocessed
            int dist = distance.get(current);
            log.info(() -> "Reached " + current + " at " + dist + " hop(s)");

            for (String neighbour : graph.getOrDefault(current, List.of())) {
                // visited.add returns false if already seen → skip to avoid cycles.
                if (visited.add(neighbour)) {
                    distance.put(neighbour, dist + 1);
                    queue.offer(neighbour);                // enqueue for a later ring
                }
            }
        }
        log.info(() -> "BFS complete. Reachable accounts: " + visited.size());
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
